func check(_ condition: @autoclosure () -> Bool) { precondition(condition()) }
check(JerkgramFolderOrder.bounded([4, 4, 0, -1, 5]) == [4, 0, 5])
check(JerkgramFolderOrder.bounded(Array(1...400).map(Int32.init)).count == 256)
check(JerkgramFolderOrder.bounded(Array(1...400).map(Int32.init)).contains(0))
let native: [Int32] = [0, 2, 3, 4, 5]
check(JerkgramFolderOrder.effective(native: native, saved: [3, 0, 2, 5], allowed: [2, 3], active: true) == [3, 0, 2, 4, 5])
check(JerkgramFolderOrder.effective(native: native, saved: [5, 3, 0, 2], allowed: [2, 3], active: true) == [0, 3, 2, 4, 5])
check(JerkgramFolderOrder.effective(native: native, saved: [99, 3, 0], allowed: [2, 3], active: true).first == 0)
check(JerkgramFolderOrder.effective(native: native, saved: [3, 0], allowed: [2, 3], active: false) == native)
check(JerkgramFolderOrder.server(native: native, accepted: [3, 0, 2, 4, 5]) == [0, 3, 2, 4, 5])
check(JerkgramFolderOrder.server(native: [2, 3], accepted: [3, 0, 2]) == [3, 2])
check(JerkgramFolderOrder.pruned(saved: [3, 2, 0], old: native, new: [0, 2, 4, 5]) == [0, 2])
check(JerkgramFolderOrder.pruned(saved: [3, 2, 0], old: [], new: []) == [3, 2, 0])
let pruned = JerkgramFolderOrder.pruned(saved: [3, 2, 0], old: native, new: [0, 2])
check(JerkgramFolderOrder.effective(native: [0, 2, 3], saved: pruned, allowed: [2, 3], active: true).first == 0)
check(JerkgramFolderOrder.proposalIsCurrent(enabled: true, premium: false, generation: 8, proposedGeneration: 8))
check(!JerkgramFolderOrder.proposalIsCurrent(enabled: true, premium: false, generation: 9, proposedGeneration: 8))
check(!JerkgramFolderOrder.proposalIsCurrent(enabled: false, premium: false, generation: 8, proposedGeneration: 8))
check(!JerkgramFolderOrder.proposalIsCurrent(enabled: true, premium: true, generation: 8, proposedGeneration: 8))
check(!JerkgramFolderOrder.proposalIsCurrent(enabled: true, premium: nil, generation: 8, proposedGeneration: 8))
JerkgramDefaultFolderSettings.update(accountPeerId: 123456789, enabled: true)
let generation = JerkgramDefaultFolderSettings.generation(accountPeerId: 123456789)
JerkgramDefaultFolderSettings.update(accountPeerId: 123456789, enabled: true)
check(generation == JerkgramDefaultFolderSettings.generation(accountPeerId: 123456789))
JerkgramDefaultFolderSettings.update(accountPeerId: 123456789, enabled: false)
check(generation != JerkgramDefaultFolderSettings.generation(accountPeerId: 123456789))

check(!JerkgramFolderOrder.startupReady(enabled: true, premium: nil, localRead: true))
check(!JerkgramFolderOrder.startupReady(enabled: true, premium: false, localRead: false))
check(JerkgramFolderOrder.startupReady(enabled: true, premium: false, localRead: true))
check(JerkgramFolderOrder.startupReady(enabled: false, premium: nil, localRead: true))
let encoded = try! JSONEncoder().encode(JerkgramDefaultFolderOrder(ids: [3, 3, 0, 2]))
check(try! JSONDecoder().decode(JerkgramDefaultFolderOrder.self, from: encoded).ids == [3, 0, 2])

let databaseA = NSObject()
let databaseB = NSObject()
let proposal = JerkgramFolderProposalToken(lifetime: databaseA, generation: 1)
check(proposal.matches(lifetime: databaseA, generation: 1))
check(!proposal.matches(lifetime: databaseB, generation: 1))
check(!proposal.matches(lifetime: databaseA, generation: 2))
check(JerkgramFolderOrder.pruned(saved: [3, 0, 2], old: [0, 2, 3], new: []) == [0])
check(JerkgramFolderOrder.effective(native: [0, 2, 4], saved: [3, 2, 0], allowed: [2], active: true) == [0, 2, 4])
check(JerkgramFolderOrder.effective(native: native, saved: [3, 3, 99, 0, 2], allowed: [2, 3], active: true) == [3, 0, 2, 4, 5])

JerkgramDefaultFolderSettings.update(accountPeerId: 987654321, enabled: true)
check(!JerkgramDefaultFolderSettings.enabled(accountPeerId: 123456789))
check(JerkgramDefaultFolderSettings.enabled(accountPeerId: 987654321))
JerkgramDefaultFolderSettings.update(accountPeerId: 987654321, enabled: false)
print("default-folder production policy fixtures passed")
